package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/items/{itemId}/history") public class PasswordHistoryController{private final PasswordHistoryService service;public PasswordHistoryController(PasswordHistoryService s){service=s;}@PostMapping public Mono<PasswordHistoryView> record(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId,@Valid@RequestBody RecordPasswordHistoryRequest r){return service.record(a,itemId,r);}@GetMapping public Flux<PasswordHistoryView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId){return service.list(a,itemId);}}
